//! Runtime support for code generated by `#[mcp_tool]`.
//!
//! Parameter classification is type-based, using autoref specialization: the
//! macro emits `(&&&Arg::<T>::new()).__mcp_extract(&cx, "name")` for every
//! parameter, and method resolution picks the first matching impl:
//!
//! | receiver      | matches                                  | source          |
//! |---------------|------------------------------------------|-----------------|
//! | `&&&Arg<T>`   | `Window`, `Webview`, `WebviewWindow`     | compile error   |
//! | `&&Arg<T>`    | `State<'_, T>`                           | `app.state()`   |
//! | `&Arg<T>`     | `AppHandle<R>`                           | handle clone    |
//! | `Arg<T>`      | `T: DeserializeOwned`                    | MCP arguments   |
//!
//! Because this keys on the resolved type, type aliases of `State` or
//! `AppHandle` work, and aliased window types are still rejected.

use std::marker::PhantomData;

use serde::{Serialize, de::DeserializeOwned};
use serde_json::{Map, Value};
use tauri::{AppHandle, Manager, Runtime, State, Webview, WebviewWindow, Window, ipc::InvokeError};

use crate::ToolError;

/// Per-call context the generated code extracts arguments from.
pub struct Cx<'a, R: Runtime> {
    app: &'a AppHandle<R>,
    args: &'a Map<String, Value>,
    tool: &'static str,
}

impl<'a, R: Runtime> Cx<'a, R> {
    pub fn new(app: &'a AppHandle<R>, args: &'a Map<String, Value>, tool: &'static str) -> Self {
        Self { app, args, tool }
    }
}

/// Zero-sized type tag for one parameter.
pub struct Arg<T>(PhantomData<fn() -> T>);

// Manual impls: the derives would require `T: Copy`.
impl<T> Clone for Arg<T> {
    fn clone(&self) -> Self {
        *self
    }
}
impl<T> Copy for Arg<T> {}

impl<T> Arg<T> {
    #[allow(clippy::new_without_default)]
    pub const fn new() -> Self {
        Self(PhantomData)
    }
}

#[diagnostic::on_unimplemented(
    message = "`{Self}` can't be a parameter of an `#[mcp_tool]` command",
    label = "window-bound parameter",
    note = "an MCP tool call has no calling window, so `Window`, `Webview` and `WebviewWindow` can't be injected",
    note = "take an `AppHandle` instead and look the window up, e.g. `app.get_webview_window(\"main\")`"
)]
pub trait McpToolArgNotWindowBound {}

/// Highest priority: window-bound types, which always fail to compile.
pub trait ExtractWindowBound {
    type Out;
    fn __mcp_extract<R: Runtime>(self, cx: &Cx<'_, R>, name: &'static str) -> Result<Self::Out, ToolError>
    where
        Self::Out: McpToolArgNotWindowBound;
}

macro_rules! window_bound {
    ($($ty:ident),*) => {$(
        impl<W: Runtime> ExtractWindowBound for &&&Arg<$ty<W>> {
            type Out = $ty<W>;
            fn __mcp_extract<R: Runtime>(self, _: &Cx<'_, R>, _: &'static str) -> Result<Self::Out, ToolError>
            where
                Self::Out: McpToolArgNotWindowBound,
            {
                unreachable!()
            }
        }
    )*};
}
window_bound!(Window, Webview, WebviewWindow);

#[diagnostic::on_unimplemented(
    message = "`{Self}` can't be a parameter of an `#[mcp_tool]` command",
    label = "IPC-only parameter",
    note = "`Channel`, `Request`, `CommandScope` and `GlobalScope` come from a webview IPC call, which an MCP tool call doesn't have",
    note = "split the logic into a function both the command and a separate `#[mcp_tool]` fn can call"
)]
pub trait McpToolArgNotIpcBound {}

/// Same priority as window types: Tauri parameters that only exist for IPC calls.
pub trait ExtractIpcBound {
    type Out;
    fn __mcp_extract<R: Runtime>(self, cx: &Cx<'_, R>, name: &'static str) -> Result<Self::Out, ToolError>
    where
        Self::Out: McpToolArgNotIpcBound;
}

macro_rules! ipc_bound {
    ($([$($g:tt)*] $ty:ty),*) => {$(
        impl<$($g)*> ExtractIpcBound for &&&Arg<$ty> {
            type Out = $ty;
            fn __mcp_extract<R: Runtime>(self, _: &Cx<'_, R>, _: &'static str) -> Result<Self::Out, ToolError>
            where
                Self::Out: McpToolArgNotIpcBound,
            {
                unreachable!()
            }
        }
    )*};
}
ipc_bound!(
    [T] tauri::ipc::Channel<T>,
    ['a] tauri::ipc::Request<'a>,
    [T: tauri::ipc::ScopeObject] tauri::ipc::CommandScope<T>,
    [T: tauri::ipc::ScopeObject] tauri::ipc::GlobalScope<T>
);

pub trait ExtractState {
    type Target: Send + Sync + 'static;
    fn __mcp_extract<'a, R: Runtime>(
        self,
        cx: &Cx<'a, R>,
        name: &'static str,
    ) -> Result<State<'a, Self::Target>, ToolError>;
}

impl<T: Send + Sync + 'static> ExtractState for &&Arg<State<'_, T>> {
    type Target = T;
    fn __mcp_extract<'a, R: Runtime>(self, cx: &Cx<'a, R>, name: &'static str) -> Result<State<'a, T>, ToolError> {
        cx.app.try_state::<T>().ok_or_else(|| {
            ToolError::Internal(format!(
                "state not managed for parameter `{name}` of tool `{}`; call `.manage()` before starting the MCP server",
                cx.tool
            ))
        })
    }
}

pub trait ExtractAppHandle<R: Runtime> {
    fn __mcp_extract(self, cx: &Cx<'_, R>, name: &'static str) -> Result<AppHandle<R>, ToolError>;
}

impl<R: Runtime> ExtractAppHandle<R> for &Arg<AppHandle<R>> {
    fn __mcp_extract(self, cx: &Cx<'_, R>, _: &'static str) -> Result<AppHandle<R>, ToolError> {
        Ok(cx.app.clone())
    }
}

pub trait ExtractInput {
    type Out;
    fn __mcp_extract<R: Runtime>(self, cx: &Cx<'_, R>, name: &'static str) -> Result<Self::Out, ToolError>;
}

impl<T: DeserializeOwned> ExtractInput for Arg<T> {
    type Out = T;
    fn __mcp_extract<R: Runtime>(self, cx: &Cx<'_, R>, name: &'static str) -> Result<T, ToolError> {
        match cx.args.get(name) {
            Some(value) => T::deserialize(value)
                .map_err(|e| ToolError::InvalidArgs(format!("invalid argument `{name}`: {e}"))),
            // Missing keys deserialize from `null`, so `Option<T>` parameters may be omitted.
            None => T::deserialize(&Value::Null)
                .map_err(|_| ToolError::InvalidArgs(format!("missing required argument `{name}`"))),
        }
    }
}

/// Whether a parameter is an MCP input (as opposed to injected by the plugin).
/// Mirrors the extraction priority above.
pub trait IsInputWindowBound {
    fn __mcp_is_input(self) -> bool;
}
impl<W: Runtime> IsInputWindowBound for &&&Arg<Window<W>> {
    fn __mcp_is_input(self) -> bool {
        false
    }
}
impl<W: Runtime> IsInputWindowBound for &&&Arg<Webview<W>> {
    fn __mcp_is_input(self) -> bool {
        false
    }
}
impl<W: Runtime> IsInputWindowBound for &&&Arg<WebviewWindow<W>> {
    fn __mcp_is_input(self) -> bool {
        false
    }
}
pub trait IsInputState {
    fn __mcp_is_input(self) -> bool;
}
impl<T: Send + Sync + 'static> IsInputState for &&Arg<State<'_, T>> {
    fn __mcp_is_input(self) -> bool {
        false
    }
}
pub trait IsInputAppHandle {
    fn __mcp_is_input(self) -> bool;
}
impl<R: Runtime> IsInputAppHandle for &Arg<AppHandle<R>> {
    fn __mcp_is_input(self) -> bool {
        false
    }
}
pub trait IsInputValue {
    fn __mcp_is_input(self) -> bool;
}
impl<T> IsInputValue for Arg<T> {
    fn __mcp_is_input(self) -> bool {
        true
    }
}

/// Return value mapping, called as `(&ret).__mcp_kind().into_value(ret)`.
/// `Result<T, E>` matches first (by-value receiver on `&Result`), any other
/// `T: Serialize` second, the same scheme Tauri uses for command responses.
pub struct ResultTag;
pub struct ValueTag;

pub trait ResultKind {
    fn __mcp_kind(&self) -> ResultTag {
        ResultTag
    }
}
impl<T: Serialize, E: Into<InvokeError>> ResultKind for Result<T, E> {}

pub trait ValueKind {
    fn __mcp_kind(&self) -> ValueTag {
        ValueTag
    }
}
impl<T: Serialize> ValueKind for &T {}

impl ResultTag {
    pub fn into_value<T: Serialize, E: Into<InvokeError>>(self, ret: Result<T, E>) -> Result<Value, ToolError> {
        match ret {
            Ok(v) => ValueTag.into_value(v),
            Err(e) => Err(ToolError::Command(e.into().0)),
        }
    }
}

impl ValueTag {
    pub fn into_value<T: Serialize>(self, ret: T) -> Result<Value, ToolError> {
        serde_json::to_value(ret).map_err(|e| ToolError::Internal(format!("failed to serialize result: {e}")))
    }
}

/// Schema glue for the `schemars` fallback, same autoref scheme: injected
/// parameters have no schema, `Option<T>` parameters are optional.
#[cfg(feature = "schemars")]
pub mod schemars_glue {
    use std::marker::PhantomData;

    use schemars::{JsonSchema, Schema, SchemaGenerator};
    use tauri::{AppHandle, Runtime, State};

    pub use super::Arg;

    pub trait SchemarsOption {
        fn __mcp_schemars(self, g: &mut SchemaGenerator) -> Option<(Schema, bool)>;
    }
    impl<T: JsonSchema> SchemarsOption for &&&Arg<Option<T>> {
        fn __mcp_schemars(self, g: &mut SchemaGenerator) -> Option<(Schema, bool)> {
            Some((g.subschema_for::<Option<T>>(), true))
        }
    }
    pub trait SchemarsState {
        fn __mcp_schemars(self, g: &mut SchemaGenerator) -> Option<(Schema, bool)>;
    }
    impl<T: Send + Sync + 'static> SchemarsState for &&Arg<State<'_, T>> {
        fn __mcp_schemars(self, _: &mut SchemaGenerator) -> Option<(Schema, bool)> {
            None
        }
    }
    pub trait SchemarsAppHandle {
        fn __mcp_schemars(self, g: &mut SchemaGenerator) -> Option<(Schema, bool)>;
    }
    impl<R: Runtime> SchemarsAppHandle for &Arg<AppHandle<R>> {
        fn __mcp_schemars(self, _: &mut SchemaGenerator) -> Option<(Schema, bool)> {
            None
        }
    }
    pub trait SchemarsValue {
        fn __mcp_schemars(self, g: &mut SchemaGenerator) -> Option<(Schema, bool)>;
    }
    impl<T: JsonSchema> SchemarsValue for Arg<T> {
        fn __mcp_schemars(self, g: &mut SchemaGenerator) -> Option<(Schema, bool)> {
            Some((g.subschema_for::<T>(), false))
        }
    }

    /// Return-type tag: `Result<T, E>` reports `T`.
    pub struct Ret<T>(PhantomData<fn() -> T>);
    impl<T> Clone for Ret<T> {
        fn clone(&self) -> Self {
            *self
        }
    }
    impl<T> Copy for Ret<T> {}
    impl<T> Ret<T> {
        #[allow(clippy::new_without_default)]
        pub const fn new() -> Self {
            Self(PhantomData)
        }
    }
    pub trait SchemarsResult {
        fn __mcp_schemars_out(self, g: &mut SchemaGenerator) -> Option<Schema>;
    }
    impl<T: JsonSchema, E> SchemarsResult for &Ret<Result<T, E>> {
        fn __mcp_schemars_out(self, g: &mut SchemaGenerator) -> Option<Schema> {
            Some(g.subschema_for::<T>())
        }
    }
    pub trait SchemarsOutput {
        fn __mcp_schemars_out(self, g: &mut SchemaGenerator) -> Option<Schema>;
    }
    impl<T: JsonSchema> SchemarsOutput for Ret<T> {
        fn __mcp_schemars_out(self, g: &mut SchemaGenerator) -> Option<Schema> {
            Some(g.subschema_for::<T>())
        }
    }
}
